Task: Push the orange puck so that its centre ends up inside the green circle. The puck is too wide to grasp.

Skill code (numbered):
  1| import math
  2| import numpy as np
  3| 
  4| def run(robot):
  5|     # Workspace bounds
  6|     X_MIN, X_MAX = 0.04, 0.32
  7|     Y_MIN, Y_MAX = -0.26, 0.26
  8|     
  9|     def clamp_xy(x, y):
 10|         return (max(X_MIN, min(X_MAX, x)), max(Y_MIN, min(Y_MAX, y)))
 11|     
 12|     def rotate_vec(v, angle):
 13|         ca, sa = math.cos(angle), math.sin(angle)
 14|         return np.array([ca * v[0] - sa * v[1], sa * v[0] + ca * v[1]])
 15|     
 16|     max_attempts = 8
 17|     push_z = 0.02          # tool-point height: finger pads ~0.0075, puck centre ~0.01
 18|     approach_base = 0.05   # 2 cm behind puck edge (radius 0.03 + 0.02)
 19|     
 20|     for attempt in range(max_attempts):
 21|         obs = robot.observe()
 22|         puck = obs["objects"]["puck"]
 23|         target = obs["fixtures"]["target"]
 24|         
 25|         puck_pos = np.array(puck["pos"])
 26|         target_pos = np.array(target["pos"])
 27|         target_radius = target["radius"]
 28|         puck_radius = puck["size"]["radius"]
 29|         
 30|         # Vector from puck to target (XY only)
 31|         to_target = target_pos[:2] - puck_pos[:2]
 32|         dist_to_target = np.linalg.norm(to_target)
 33|         
 34|         if dist_to_target <= target_radius + 1e-3:
 35|             robot.log(f"Success: puck in target, dist={dist_to_target:.4f}")
 36|             return True
 37|         
 38|         # Base push direction
 39|         push_dir = to_target / dist_to_target
 40|         
 41|         # Lead angle to counteract sideways slide of upright puck
 42|         lead_angle = puck_radius / max(dist_to_target, 0.01)
 43|         push_dir = rotate_vec(push_dir, lead_angle)
 44|         
 45|         # Check puck orientation: yaw in [-pi/4, pi/4), 0 = faces aligned with world axes
 46|         # Edge-on when |yaw| ~ pi/4. Dot product with push_dir indicates face-on vs edge-on.
 47|         puck_yaw = puck["yaw"]
 48|         puck_forward = np.array([math.cos(puck_yaw), math.sin(puck_yaw)])
 49|         face_on = abs(np.dot(puck_forward, push_dir))
 50|         
 51|         # If edge-on (face_on < 0.5), increase approach distance and raise push_z slightly
 52|         approach_dist = approach_base
 53|         local_push_z = push_z
 54|         if face_on < 0.5:
 55|             approach_dist += 0.02
 56|             local_push_z += 0.01
 57|         
 58|         # Start position behind puck
 59|         start_xy = puck_pos[:2] - push_dir * approach_dist
 60|         start_xy = clamp_xy(start_xy[0], start_xy[1])
 61|         
 62|         # End position: push past target by puck_radius + margin
 63|         push_distance = dist_to_target + puck_radius + 0.02
 64|         end_xy = puck_pos[:2] + push_dir * push_distance
 65|         end_xy = clamp_xy(end_xy[0], end_xy[1])
 66|         
 67|         # Move to start: above first, then down
 68|         try:
 69|             robot.move_to(start_xy[0], start_xy[1], 0.10, speed=0.15)
 70|             robot.move_to(start_xy[0], start_xy[1], local_push_z, speed=0.05)
 71|         except Exception as e:
 72|             robot.log(f"Move to start failed: {e}")
 73|             continue
 74|         
 75|         # Push forward
 76|         try:
 77|             robot.move_to(end_xy[0], end_xy[1], local_push_z, speed=0.05)
 78|         except Exception as e:
 79|             robot.log(f"Push move failed: {e}")
 80|             continue
 81|         
 82|         robot.wait(0.2)  # let physics settle
 83|     
 84|     # Final check after attempts
 85|     obs = robot.observe()
 86|     puck = obs["objects"]["puck"]
 87|     target = obs["fixtures"]["target"]
 88|     puck_pos = np.array(puck["pos"])
 89|     target_pos = np.array(target["pos"])
 90|     target_radius = target["radius"]
 91|     dist = np.linalg.norm(target_pos[:2] - puck_pos[:2])
 92|     robot.log(f"Final dist to target: {dist:.4f}, target radius: {target_radius:.4f}")
 93|     return dist <= target_radius

